output-exprs.el:
queueTransaction:a!localVariables(
  /* if previously deleted max, schedule to run again immediately */
  local!scheduled: if (count(pv!identifiers) >= #"_a-0000e494-3e27-8000-8592-01ef9001ef90_107428", now(), now() + intervalds(1, 0, 0)),
  'type!{urn:com:appian:types:TM}TM_QueueTransaction'(
    modelUuid: pm!uuid,
    context: {days: pv!days},
    scheduled: local!scheduled
  )
)
